package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMaiDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("अहाँक दयाक आशा करैत छी।", "ऐ अल्लाह, हम अहाँक दया के आशा करैत छी, तेँ हमरा पलक झपकय तक अपन पर नहि छोड़ि दियौक, आ हमर सभ काज ठीक कऽ दियौक। अहाँक अतिरिक्त कोनो देवता नहि अछि।", "संकटमे पड़ल लोकक दुआ (दावत अल-मक्रुब)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एकरा संकटग्रस्त लोकक दुआ कहैत छथि।"),
        "dua_against_enemy_ahzab" to DuaText("दुश्मनक सेनाक विरुद्ध", "ऐ अल्लाह, किताब प्रकट करैवला! हिसाब मे तेजी आ संघसभ केँ हरा दे। ऐ अल्लाह, ओकरा सभ केँ हरा दे आ हिला दे।", "दुश्मन के खिलाफ-संघ के लड़ाई के दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम दुश्मनक खिलाफ दुआ करैत छथि।"),
        "dua_anta_adudi" to DuaText("अहाँ हमर सहायक छी।", "ऐ अल्लाह, अहाँ हमर सहारा आ हमर सहायक छी। हम अहाँ द्वारा योजना करैत छी, अहाँ द्वारा आगू बढ़ैत छी आ अहाँ द्वारा लड़ैत छी।", "कोनो प्रतियोगिता वा कोनो पैघ चुनौतीसँ पहिने।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम युद्धमे ई कहलनि।"),
        "dua_ikfinihim" to DuaText("हमरा हुनका सभक विरुद्ध पर्याप्त करू।", "ऐ अल्लाह, अहाँ जे चाहू, हमरा हुनका सभक विरुद्ध पर्याप्त करू।", "उत्पीड़क दुष्टताक विरुद्ध-द पीपल ऑफ द डिचक कथामे बालकक दुआ।", "अल्लाह बालककेँ उत्पीड़क सँ बचौलनि।"),
        "dua_qadarullah" to DuaText("जखन किछु खराब होइत अछि।", "ई अल्लाह के फरमान अछि, आ ओ जे चाहैत छलाह, से कयलनि।", "जखन किछु अप्रिय होइत अछि तखन'यदि मात्र'कहबाक बदला।", "'यदि मात्र'शैतानक द्वार खोलैत अछि।"),
        "dua_ala_kulli_hal" to DuaText("प्रत्येक परिस्थितिमे प्रशंसा करू।", "प्रत्येक परिस्थिति मे प्रशंसा अल्लाह के लेल अछि।", "जखन किछु नापसंद होइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कोनो एहन बातक सामना करय पर ई कहलनि जे हुनका नापसंद छल।"),
        "dua_dogs_barking" to DuaText("रातिमे कुकुरसभ भौंकैत अछि।", "हम शापित शयतान सँ अल्लाह मे शरण चाहैत छी।", "रातिमे कुकुरक भौंकने वा गदहकेँ भुनय के आवाज सुनला पर।", "ओ सभ ओहि वस्तु सभ केँ देखैत अछि जे अहाँ नहि देखैत छी।"),
        "dua_leaving_home_adilla" to DuaText("भटकयसँ शरण", "ऐ अल्लाह, हम अहाँ मे शरण चाहैत छी जे हम पथभ्रष्ट नहि होऊ वा पथभ्रष्ट भऽ जाऊ, अन्यथा हम पथभ्रष्ट नहि होऊ वा पथभ्रष्ट भऽ जाऊ, अन्यथा हमरा पर अन्याय नहि भऽ सकैत अछि वा हमरा पर अन्याय भऽ सकैत अछि, अन्यथा हमरा मूर्खतापूर्ण व्यवहार नहि भऽ सकैत अछि वा मूर्खतापूर्ण व्यवहार कयल जा सकैत अछि।", "घरसँ बाहर निकलबाक समय-उम्म सलामाह (रा.) द्वारा वर्णित।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम जखन-जखन घरसँ बाहर निकलैत छलाह तँ ई पाठ करैत छलाह।"),
        "dua_ascending_descending" to DuaText("ऊपर आ नीचा आबि रहल अछि।", "अल्लाह सबसँ महान छथि (जखन ओ ऊपर जाइत छथि)। महिमावान छथि अल्लाह।", "यात्रा मे ऊपर जाय पर'अल्लाहू अकबर'आ नीचा उतरय पर'सुभानल्लाह'कहि लिअ।", "यात्रा करैत काल साथी (आर. ए.) क अभ्यास।"),
        "dua_traveller_sahar" to DuaText("भोरसँ पहिने यात्रीक दुआ", "एक श्रोता परमेश्वरक प्रशंसा आ हमरा सभ पर हुनकर नीक बरकत सुनलनि। हमर प्रभु, हमरा सभक संग जाउ आ हमरा सभ पर अहाँक बरकत करू-(हम ई कहैत छी) आगि सँ अल्लाहमे शरण लऽ कऽ।", "यात्रा पर, भोरसँ पहिने।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम भोरसँ पहिने यात्रा करैत काल ई कहलनि।"),
        "dua_zawwadakallah" to DuaText("यात्रीकेँः अल्लाह तक्वा प्रदान करे।", "अल्लाह अहाँक यात्राक लेल तक्वा प्रदान करय, अहाँक पाप क्षमा करय आ अहाँ जतऽ सेहो रही अहाँक लेल भलाइकेँ सहज बना दे।", "जखन कोनो यात्रीकेँ विदाई दैत छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम यात्राक लेल रवाना भेल कोनो व्यक्तिकेँ ई दुआ देलनि।"),
        "dua_traveller_to_resident" to DuaText("यात्रीसँ ओहि सभ लेल जे पीछे रहैत छथि", "हम अहाँ सभ केँ अल्लाह के सौंपैत छी, जकर विश्वास कखनो नहि हारि जाइत अछि।", "परिवार केँ विदाई दैत यात्री द्वारा कहल गेल।", "परिवारक सुरक्षा अल्लाहकेँ सौंपनाय।"),
        "dua_entering_village" to DuaText("कोनो नगर वा गाम मे प्रवेश करब", "ऐ अल्लाह, सात आकाशक और ओकर छाया सभक प्रभु, सात पृथ्वीक और ओकर सब किछाक प्रभु, शैतानक और ओकर सभ पथभ्रष्ट करबाक प्रभु, हवाक आ ओकर सभ केँ जे ओ बिखेरैत अछि, ओकर प्रभु! हम अहाँ सँ एहि नगरक भलाइ आ ओकर लोकक भलाइ माँगैत छी, आ हम अहाँ सँ ओकर अधलाह, ओकर लोकक अधलाह आ ओहि मे जे किछु अछि ओकर अधलाह सँ शरण लैत छी।", "कोनो शहर वा नगरमे प्रवेश करबासँ पहिने।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम जखन कोनो नगरमे प्रवेश करबाक इच्छा करैत छलाह तँ ई पाठ करैत छलाह।"),
        "dua_vehicle_stumbles" to DuaText("जखन गाड़ी लड़खड़ा जाइत अछि", "अल्लाह के नाम पर।", "जखन'शयतान नष्ट भऽ जाय'कहबाक बदला, चढ़ाई या वाहन फिसल जायत अछि या लड़खड़ैत अछि।", "बिस्मिल्लाह कहलासँ शैतान एकटा मक्खीक आकार धरि सिकुड़ैत अछि।"),
        "dua_ajz_kasal_haram" to DuaText("कमजोरी आ वृद्धावस्थासँ शरण", "हे अल्लाह, हम अहाँ मे असहायता आ आलस्य, कायरता आ वृद्धावस्था, जीवन आ मृत्युक परीक्षण आ कब्रक सजा सँ शरण चाहैत छी।", "आश्रयक एकटा व्यापक दैनिक दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बहुधा दुआ करैत छलाह।"),
        "dua_sharri_ma_amiltu" to DuaText("हमर दुष्ट काजसँ शरण", "ऐ अल्लाह, हम जे किछु कयलहुँ ओकर अधलाह व्यवहार आ जे किछु नहि कयलहुँ ओकर अधलाह व्यवहार सँ अहाँक शरण चाहैत छी।", "आयशा (रा.) क अनुसार पैगम्बर सल्लल्लाहु अलैहि वसल्लम (स.) के दुआ।", "की कयल गेल आ की पूर्ववत छोड़ि देल गेल, दुनू के परिणाम सँ सुरक्षा।"),
        "dua_jahdil_bala" to DuaText("गंभीर परीक्षणसँ शरण", "हे अल्लाह, हम बड्ड कठिन परीक्षा सँ, दुख सँ, दुष्ट आदेश सँ आ दुश्मनक जय-जयसँ अहाँ मे शरण चाहैत छी।", "गम्भीर परीक्षण आ शत्रु सभक हर्षोल्लाससँ शरण।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि चारि बात सँ शरण लेलनि।"),
        "dua_fitnat_ghina_faqr" to DuaText("धन आ गरीबीक परीक्षणसँ शरण", "ऐ अल्लाह, हम आळस आ वृद्धावस्था, पाप आ ऋण, कब्रक परीक्षण आ सजा, आगि के परीक्षण आ सजा, धनक परीक्षणक दुष्टता आ गरीबी के परीक्षण सँ अहाँ मे शरण चाहैत छी।", "कब्र, नरक, धन आ गरीबी (दुआक हिस्सा) क परीक्षणसँ शरण।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सँ शरण लेल एकटा व्यापक दुआ।"),
        "dua_kufr_faqr" to DuaText("अविश्वास आ गरीबीसँ मुक्ति", "ऐ अल्लाह, हम तोँमे अविश्वास आ गरीबी सँ शरण चाहैत छी, आ कबरक सजा सँ शरण चाहैत छी। अहाँक अतिरिक्त कोनो देवता नहि अछि।", "तीन बेर भोर आ साँझ।", "अबू बक्राह (रा.) पैगम्बर (स.) केँ ई कहैत सुनलनि।"),
        "dua_sharri_sami" to DuaText("हमर इन्द्रियसभक दुष्टतासँ शरण", "हे अल्लाह, हम अहाँ मे अपन सुनने के दुष्टता, अपन दृष्टि के दुष्टता, अपन जीभ के दुष्टता, अपन हृदय के दुष्टता आ अपन इच्छा के दुष्टता सँ शरण चाहैत छी।", "शकल इब्न हुमायद (र.) केँ सिखायल गेल।", "अङ्ग आ अपन पापसँ बचयबाक लेल एकटा दुआ।"),
        "dua_hadm_gharaq" to DuaText("आकस्मिक मृत्यु आ दुर्घटनासँ शरण", "ऐ अल्लाह, हम अहाँ मे पसिन सँ (भवन द्वारा), ऊँचाइ सँ खसि सँ, डूबय सँ, जलय सँ आ वृद्धावस्था सँ, मृत्युक समय हमरा पथभ्रष्ट करै वला शैतान सँ, अहाँक मार्ग सँ भागैत काल मरिबा सँ, आ (विषाक्त) डंक सँ मरिबा सँ शरण चाहैत छी।", "दुर्घटना आ खराब मृत्युसँ शरण।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सँ शरण लेल दुआ।"),
        "dua_ju_khiyanah" to DuaText("भूख आ विश्वासघातसँ शरण", "ऐ अल्लाह, हम भूख सँ अहाँ मे शरण चाहैत छी, कारण ई एकटा दुष्ट साथी अछि, आ हम विश्वासघात सँ अहाँ मे शरण चाहैत छी, किएक तँ ई एकटा दुष्ट विश्वासपात्र अछि।", "भूख आ विश्वासघातसँ शरण।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सँ शरण लेल दुआ।"),
        "dua_huda_tuqa" to DuaText("मार्गदर्शन, धर्मनिष्ठा, शुद्धता आ पर्याप्तता", "ऐ अल्लाह, हम अहाँ सँ मार्गदर्शन, धर्मनिष्ठा, शुद्धता आ आत्मनिर्भरताक प्रार्थना करैत छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एकटा संक्षिप्त, व्यापक दुआ।", "धर्म आ एहि दुनियाक चारि मूलभूत आशीर्वाद।"),
        "dua_aslih_li_dini" to DuaText("हमर धर्म, संसार आ बाद मे सुधार करू।", "ऐ अल्लाह, हमर धर्म ठीक करू, जे हमर सभ काजक सुरक्षा अछि, हमर सांसारिक जीवन ठीक करू, जाहि मे हमर रोजी-रोटी अछि, आ अपन आख़िरत ठीक करू, जाहि पर हम फेर आबि जाऊ। हमर लेल जीवन केँ हर नीक मे वृद्धि करू, आ मृत्यु केँ हर अधलाह सँ हमरा लेल राहत करू।", "धर्म, ई संसार आ आख़िरत-ई तीनू सुधार।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एक व्यापक दुआ।"),
        "dua_musarrifal_qulub" to DuaText("अपन आज्ञाकारिता लेल अपन हृदयकेँ फेरू।", "ऐ अल्लाह, दिल फेरयवला, हमर हृदय अहाँक आज्ञाकारिता दिस फेरू।", "हृदयकेँ आज्ञाकारितामे दृढ़ रखबाक लेल एक दुआ।", "सभ लोकक हृदय परम करुणामय के दू अंगुली के बीच मे रहैत अछि।"),
        "dua_jannah_nar" to DuaText("जन्नत, आगिसँ शरण माँगैत।", "ऐ अल्लाह, हम अहां सँ स्वर्ग माँगैत छी आ आगि सँ अहाँ मे शरण चाहैत छी।", "ताशाहहुदक बाद वा कोनो समय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि, \"हमर दुआ सेहो एकर इर्द-गिर्द घुमैत अछि।"),
        "dua_khayri_kullih" to DuaText("सब ठीक अछि, आब आ बाद मे", "ऐ अल्लाह, हम अहाँक सभ नीक काजक लेल प्रार्थना करैत छी-तत्काल आ विलंबित, जे हम जनैत छी आ जे नहि जनैत छी-आ हम अहाँ मे सभ अधलाह काज-तत्काल आ विलंबित, जे हम जनैत छी आ जे नहि जनैत छी, तकरा सँ शरण लैत छी। हे अल्लाह, हम अहाँ सँ स्वर्गक लेल प्रार्थना करैत छी आ जे किछु शब्द आ काज हमरा ओकर करीब अनैत अछि, आ हम आगिसँ अहाँ मे शरण लैत छी आ जे किछु शब्द आ काज हमरा ओकर करीब अनैत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम आयशा (रा.) (दुआक हिस्सा) केँ ई व्यापक दुआ सिखौलनि।", "एकटा दुआ जे सब नीक काजकेँ एकत्रित करैत अछि।"),
        "dua_ihdini_saddidni" to DuaText("हमरा मार्गदर्शन करू आ हमरा सही राखू।", "ऐ अल्लाह, हमरा मार्गदर्शन करू आ सही मार्ग पर चलू।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ई बात अली (र.) केँ सिखौलनि।", "मार्गमे मार्गदर्शनकेँ निर्देशित करबाक रूपमे आ साददकेँ तीरक सीधापनक रूपमे सोचि लिअ।"),
        "dua_hubbaka" to DuaText("अल्लाहसँ प्रेम माँगब।", "ऐ अल्लाह, हम अहां सँ प्रेम माँगैत छी, तकरा सभ सँ प्रेम जे अहाँ सँ प्रेम करैत अछि, आ एहन काज जे हमरा अहाँक प्रेम मे लबैत अछि। ऐ अल्लाह, हमरा लेल अहाँक प्रेम केँ हमरा, हमर परिवार आ ठंडा पानि सँ बेसी प्रिय बनाउ।", "दावूद (अ. स.) क दुआ पैगम्बर सल्लल्लाहु अलैहि वसल्लम द्वारा सम्बन्धित अछि।", "अल्लाह के प्रेम सबसँ पैघ धन अछि।"),
        "dua_filal_khayrat" to DuaText("नीक काज करब आ बुराई छोड़ि देब।", "ऐ अल्लाह, हम अहाँ सँ प्रार्थना करैत छी जे अहाँ हमरा नीक काज करबाक, अधलाह काज छोड़ि गरीब सँ प्रेम करबाक, आ अहाँ हमरा क्षमा कऽ दियौक आ हमरा पर दया करू। आ जखन अहाँ कोनो लोकक लेल परीक्षण करबाक इरादा करैत छी तँ हमरा बिना परीक्षणक लऽ लिअ। हम अहाँ सँ प्रेम, अहाँ सँ प्रेम करय वला सभक प्रेम, आ ओहि काज सभक प्रेम जे हमरा अहाँक प्रेमक करीब अनैत अछि, ई प्रार्थना करैत छी।", "अल्लाह ई दुआ पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ सपना मे सिखौलनि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि जे ई सत्य अछि, तेँ ई सीखो आ सिखाओ।"),
        "dua_bi_ilmikal_ghayb" to DuaText("हमरा जीवित रहबाक दे, जखन जीवन नीक अछि।", "ऐ अल्लाह, अपन अदृश्यक ज्ञान आ सृष्टिक पर अपन सामर्थ्यसँ हमरा जीवित राखू, जतऽ धरि अहाँ जनैत छी जे जीवन हमरा लेल नीक अछि, आ हमरा लऽ लिअ जखन अहाँ जनैत छी जे मृत्यु हमरा लेल नीक अछि। हे अल्लाह, हम अहाँ सँ अनुरोध करैत छी जे अहाँ गुप्त आ सार्वजनिक रूप सँ डरू, संतोष आ क्रोध मे सत्यक वचन, आ गरीबी आ धन मे संयम राखू।", "अम्मार इब्न यासिर (रा.) (उद्घाटन भाग) क प्रार्थना दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम प्रार्थना मे ई दुआ कयलनि।"),
        "dua_ism_azam_mannan" to DuaText("इस्मे-ए-आजमः अल-मन्नान", "ऐ अल्लाह, हम अहाँ सँ प्रार्थना करैत छी जे, समस्त प्रशंसा अहाँक अछि, अहाँक अतिरिक्त कोनो पूज्य-प्रभु नहि अछि, जे अनुग्रहक दाता छथि, आकाश आ पृथ्वीक निर्माता छथि। ऐ महानता आ सम्मानक स्वामी, ऐ जीवित, ऐ पालनकर्ता!", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि जे ई व्यक्ति अल्लाह के महान नाम सँ दुआ बनौलनि।", "एहि नामसँ बनल दुआक उत्तर देल जाइत अछि।"),
        "dua_ism_azam_ahad_samad" to DuaText("इस्मे-ए-आजमः अल-अहद अस-समद", "ऐ अल्लाह, हम अहाँ सँ प्रार्थना करैत छी, कारण हम अहाँ के गवाह दैत छी जे अहाँ अल्लाह छी; अहाँक अतिरिक्त कोनो देवता नहि अछि, एक, आत्मनिर्भर, जे न तो जन्म लैत अछि आ न जन्मैत अछि, आ न ओकर कोनो तुलनीय अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि जे ई व्यक्ति अल्लाहसँ हुनकर महानतम नाम पूछलनि।", "जखन ओ ई पूछैत छथि तँ दैत छथि; जखन ओ एकरा द्वारा पुकारैत छथि तँ ओ उत्तर दैत छथि।"),
        "dua_thabbitni_hadiyan" to DuaText("हमरा दृढ़, निर्देशित आ मार्गदर्शक बनाउ।", "ऐ अल्लाह, हमरा स्थिर बनाउ आ हमरा मार्गदर्शन करय वला आ मार्ग देखाबय वला बनाउ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम जरीर (रा) (अपन लेल'थाबितनी') क लेल ई दुआ बनौलनि।", "जरीर (आर. ए.) क मूल दुआमे'थब्बित-हु'शब्दक प्रयोग कयल गेल अछि।"),
        "dua_rabbighfir_tub_alayya" to DuaText("हमरा क्षमा करू आ हमर पश्चाताप स्वीकार करू।", "हे हमर प्रभु, हमरा क्षमा करू आ हमर पश्चाताप स्वीकार करू। निश्चय ही अहाँ पश्चाताप करबाक अग्रदूत, दयावान छी।", "एक बैठकमे सौ बेर-पैगम्बर सल्लल्लाहु अलैहि वसल्लमक अभ्यास।", "साथी लोकनि पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एक बैठक मे सौ बेर ई कहैत गनाइक।"),
        "dua_rafiq_ala" to DuaText("मृतक व्यक्तिक दुआ", "ऐ अल्लाह, हमरा क्षमा करू, हमरा पर दया करू आ सर्वोच्च साथी संग हमरा संग जाउ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के अन्तिम दुआ-बीमार व्यक्ति के लेल जे ओ स्वयं कहि सकय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अपन निधनक समय ई दुआ कयलनि।"),
        "dua_la_bas_tahur" to DuaText("बीमारकेँ सांत्वनाः शुद्धिकरण", "कोनो हानि नहि; ई (पापसँ) शुद्धिकरण अछि, जँ अल्लाह चाहैत छथि।", "दौरा करैत समय बीमारकेँ सांत्वना देबाक लेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ई बात बीमार सभ सँ भेंट करैत काल कहलनि।"),
        "dua_talqeen" to DuaText("मरने वालों के लिए तलकीन", "अल्लाह के अलावा ककरो पूजा करबाक अधिकार नहि अछि।", "एकटा मृत व्यक्तिक लग कलिमा पठू (ओकरा ई कहने लेल मजबूर नहि करू)।", "जकर अन्तिम शब्द'ला इलाहा इल्लल्लाह'होयत ओ स्वर्गमे प्रवेश करत (अबू दाउद 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("मृत्यु के कामना के बजाय", "ऐ अल्लाह, हमरा जीवित राखू जाबत धरि जीवन हमरा लेल बेहतर होयत, आ हमरा लऽ लिअ जखन मृत्यु हमरा लेल बेहतर होयत।", "कठिन परिस्थितिमे मृत्युक कामना करबाक बदला।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम मृत्युक कामना करबासँ मना कयलनि आ एकर बदला ई सिखौलनि।"),
        "dua_for_one_i_cursed" to DuaText("कोनो लोकक लेल जे हम शब्दसँ चोट पहुँचबैत छी।", "ऐ अल्लाह, जकरा विश्वासीक हम अपमान कयलहुँ तकरा पुनरुत्थानक दिन अहाँक निकटताक साधन बनाउ।", "कोनो एहन व्यक्ति लेल जकरा सँ अहाँ क्रोध मे बुरी बात कयने छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के दुआ।"),
    )
}
